import fs from 'node:fs';import path from 'node:path';import vm from 'node:vm';import assert from 'node:assert/strict';
const shell=vm.runInNewContext(fs.readFileSync('sw.js','utf8').match(/const SHELL=(\[.*?\]);/s)[1]),cached=new Set(Array.from(shell,p=>new URL(p,'https://local/').pathname));let assets=0;
for(const file of fs.readdirSync('students').filter(f=>f.endsWith('.html'))){const html=fs.readFileSync('students/'+file,'utf8');for(const match of html.matchAll(/(?:src|href)="([^"#]+\.(?:js|css)(?:\?[^"#]*)?)"/g)){if(/^https?:/.test(match[1]))continue;const local=new URL(match[1],'https://local/students/'+file).pathname;assert.ok(fs.existsSync('.'+local),file+' missing '+local);assert.ok(cached.has(local),file+' offline shell misses '+local);assets++;}}
console.log(JSON.stringify({status:'PASS',linkedAssetsChecked:assets,scope:'Every local script and stylesheet linked by Education pages exists and is in the offline shell. Protected-preview offline restrictions remain separate.'}));
